 {page==='reports'&&<div className="report-layout"><Panel title="Organization intelligence report"><div className="report-preview"><div className="report-brand"><Shield size={22}/> ASTRA <span>INTELLIGENCE REPORT</span></div><h2>{principal.organization.name}</h2><p>{new Date().toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'})}</p><div className="report-stats"><div><b>{summary.openAlerts}</b><span>Open alerts</span></div><div><b>{cases.length}</b><span>Investigations</span></div><div><b>{summary.averageRisk}</b><span>Mean risk</span></div></div><h3>Included in the export</h3>{['Alert details and severity','Investigation status, assignments and analyst notes','Bookmarked evidence references','Analyst feedback and retraining labels','Organization metadata and generation timestamp'].map(t=><p className="inline" key={t}><Check size={15}/>{t}</p>)}<p className="muted">JSON export preserves structured evidence for downstream tools. {DEMO&&'All records in this preview are synthetic.'}</p></div></Panel><Panel title="Export report"><div className="padded"><p className="muted">Create a portable snapshot of your organization’s security activity.</p><button disabled={!canReport} className="primary full" onClick={exportReport}><Download size={16}/>Download JSON report</button><button className="full" onClick={()=>window.print()}><FileText size={16}/>Print summary / save PDF</button><p className="small muted">Exports are recorded in the backend audit trail.</p></div></Panel></div>}
